#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    string s;
    getline(cin >> ws, s);

    long long result = 0, num = 0;
    int sign = 1;
    vector<pair<long long, int>> stack;
    for (char ch : s) {
        if (ch >= '0' && ch <= '9') {
            num = num * 10 + (ch - '0');
        } else if (ch == '+' || ch == '-') {
            result += sign * num;
            num = 0;
            sign = ch == '+' ? 1 : -1;
        } else if (ch == '(') {
            stack.push_back({result, sign});
            result = 0;
            sign = 1;
        } else if (ch == ')') {
            result += sign * num;
            num = 0;
            result = stack.back().first + stack.back().second * result;
            stack.pop_back();
        }
    }
    result += sign * num;
    cout << result << "\n";

    return 0;
}

